// The agentbox command line tool. A packaged app ships the binary: the app keeps
// its own copy in ~/.local/share/agentbox/bin (the daemon runs from it, so it
// outlives the app's mount), and "Install command-line tool" links it into
// ~/.local/bin. From a checkout, the tool is linked from AGENTBOX_BIN instead.
//
// On Windows the app ships agentbox.exe, the front end of AgentBox's WSL distro
// (internal/hostwsl), and the Linux agentbox it installs in the distro, which
// it looks for beside itself: both are kept in %LOCALAPPDATA%\AgentBox\bin, and
// "Install command-line tool" puts that folder on the user's PATH.
import { execFile, execFileSync } from 'node:child_process';
import { firstCli } from './clipath';
import { createHash } from 'node:crypto';
import { chmodSync, copyFileSync, existsSync, lstatSync, mkdirSync, readdirSync, readFileSync, renameSync, statSync, symlinkSync, unlinkSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { basename, dirname, join } from 'node:path';
import { app } from 'electron';
import { t } from '../shared/i18n/index.ts';
import { leftAlone, me, ownerName, versionSaid } from './managedcopy';
import { dataDir } from './paths';
import { onWindows } from './relay';

export interface CliStatus {
  linkPath: string; // where the command is installed: ~/.local/bin/agentbox
  linked: boolean; // linkPath exists
  path: string | null; // what `agentbox` runs in a login shell, if anything
  version: string | null;
  onPath: boolean; // ~/.local/bin is on a login shell's PATH
  bundled: boolean; // this app ships an agentbox binary
  binary: string | null; // the agentbox binary the app runs, when it knows where it is
}

const exe = onWindows ? 'agentbox.exe' : 'agentbox';
const localBin = join(homedir(), '.local', 'bin');
const managedDir = onWindows ? join(process.env.LOCALAPPDATA || join(homedir(), 'AppData', 'Local'), 'AgentBox', 'bin') : join(dataDir, 'bin');
const linkPath = onWindows ? join(managedDir, exe) : join(localBin, 'agentbox');
const managedBin = join(managedDir, exe);
// On a Mac and on Windows the app also ships the Linux agentbox, which the
// front end (of AgentBox's Linux VM, or of its WSL distro) installs there. The
// front end looks for it beside itself, so it's kept beside the managed copy too.
const linuxName = 'agentbox-linux';

function bundledBin(): string | null {
  if (!app.isPackaged) return null;
  const bin = join(process.resourcesPath, 'bin', exe);
  return existsSync(bin) ? bin : null;
}

function run(cmd: string, args: string[], env?: NodeJS.ProcessEnv): Promise<string | null> {
  return new Promise((resolve) =>
    execFile(cmd, args, { timeout: 10_000, windowsHide: true, env: env ? { ...process.env, ...env } : undefined }, (err, stdout) =>
      resolve(err ? null : stdout.trim() || null),
    ),
  );
}

// keepCurrent makes dst a copy of src, unless it is one. A running .exe can't
// be replaced on Windows, but it can be renamed: the old one is moved aside,
// and removed the next time it isn't running.
function keepCurrent(src: string, dst: string): void {
  if (same(src, dst)) return;
  mkdirSync(dirname(dst), { recursive: true });
  for (const name of readdirSync(dirname(dst))) {
    if (!name.startsWith(`${basename(dst)}.old-`)) continue;
    try {
      unlinkSync(join(dirname(dst), name));
    } catch {
      // still running
    }
  }
  copyFileSync(src, dst + '.new');
  chmodSync(dst + '.new', 0o755);
  if (onWindows && existsSync(dst)) {
    const old = `${dst}.old-${Date.now()}`;
    renameSync(dst, old);
    try {
      unlinkSync(old);
    } catch {
      // still running
    }
  }
  renameSync(dst + '.new', dst);
}

function same(src: string, dst: string): boolean {
  return existsSync(dst) && statSync(dst).size === statSync(src).size && digest(dst) === digest(src);
}

function digest(file: string): string {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

// The managed copy's version, asked once per file: agentboxBin runs often.
const said = new Map<string, string | null>();

function managedVersion(): string | null {
  const stat = statSync(managedBin);
  const key = `${stat.size}:${stat.mtimeMs}`;
  if (!said.has(key)) {
    let out: string | null = null;
    try {
      out = execFileSync(managedBin, ['--version'], { timeout: 10_000, windowsHide: true, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    } catch {
      // it wouldn't say
    }
    said.set(key, versionSaid(out));
  }
  return said.get(key) ?? null;
}

function owner(): string | null {
  try {
    return readFileSync(join(managedDir, ownerName), 'utf8');
  } catch {
    return null;
  }
}

// leftTheirs is the version of the native app's managed copy, this app's
// version or a newer one, when agentboxBin left it alone (managedcopy.ts).
let leftTheirs: string | null = null;

// daemonVersion is the version of the daemon this app starts: its own, or
// that of the native app's tool, when that's the managed copy. An app from
// a checkout has none.
export function daemonVersion(): string | undefined {
  if (!app.isPackaged) return undefined;
  agentboxBin();
  return leftTheirs ?? app.getVersion();
}

// agentboxBin is the binary the app starts the daemon with.
export function agentboxBin(): string {
  if (process.env.AGENTBOX_BIN) return process.env.AGENTBOX_BIN;
  const bundled = bundledBin();
  if (!bundled) return 'agentbox';
  // Keep the app's own copy current, so the daemon and agents get this
  // version, unless the native app's is there and no older (managedcopy.ts).
  if (!same(bundled, managedBin)) {
    const theirs = existsSync(managedBin) ? managedVersion() : null;
    if (leftAlone(owner(), theirs, app.getVersion())) {
      leftTheirs = theirs;
      return managedBin;
    }
    keepCurrent(bundled, managedBin);
    writeFileSync(join(managedDir, ownerName), me);
  }
  leftTheirs = null;
  const linux = join(dirname(bundled), linuxName);
  if (existsSync(linux)) keepCurrent(linux, join(managedDir, linuxName));
  return managedBin;
}

function isLink(path: string): boolean {
  try {
    return lstatSync(path).isSymbolicLink();
  } catch {
    return false;
  }
}

// inShell runs command the way a new terminal would: the user's own shell,
// login and interactive, since zsh (a Mac's default) reads ~/.zshrc only when
// interactive. What the profile prints comes first, so the answer is the last line.
async function inShell(command: string): Promise<string | null> {
  const out = await run(process.env.SHELL || 'bash', ['-lic', command]);
  return out?.split('\n').pop()?.trim() || null;
}

export async function cliStatus(): Promise<CliStatus> {
  if (onWindows) return windowsCliStatus();
  // bash's answer too, for a shell whose PATH isn't colon-separated (fish).
  const path = (await inShell('command -v agentbox')) ?? (await run('bash', ['-lc', 'command -v agentbox']));
  const shellPath = [await inShell('printf %s "$PATH"'), await run('bash', ['-lc', 'printf %s "$PATH"'])].join(':');
  return {
    linkPath,
    linked: existsSync(linkPath) || isLink(linkPath),
    path,
    version: path ? await run(path, ['--version']) : null,
    onPath: shellPath.split(':').includes(localBin),
    bundled: bundledBin() !== null || Boolean(process.env.AGENTBOX_BIN),
    binary: bundledBin() ? agentboxBin() : (process.env.AGENTBOX_BIN ?? null),
  };
}

// installCli links the agentbox command into ~/.local/bin. It replaces an
// earlier link, but never a file it didn't make.
export async function installCli(): Promise<CliStatus> {
  const target = bundledBin() ? agentboxBin() : process.env.AGENTBOX_BIN;
  if (!target) throw new Error(t('web.main.cliNoBinary'));
  if (onWindows) {
    await addToUserPath(dirname(target));
    return cliStatus();
  }
  mkdirSync(localBin, { recursive: true });
  if (isLink(linkPath)) unlinkSync(linkPath);
  else if (existsSync(linkPath)) throw new Error(t('web.main.cliLinkExists', { path: linkPath }));
  symlinkSync(target, linkPath);
  return cliStatus();
}

// The user's own PATH, from the registry: this process's PATH is what it
// started with, and PowerShell reads the one a new terminal gets.
const userPathScript = "[Environment]::GetEnvironmentVariable('Path', 'User')";

async function userPath(): Promise<string[]> {
  const out = await run('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', userPathScript]);
  return (out ?? '').split(';').filter(Boolean);
}

// addToUserPath puts dir on the user's PATH, for terminals opened after it.
// The folder goes in through the environment, so no quoting can break it.
async function addToUserPath(dir: string): Promise<void> {
  const script = `$d = $env:AGENTBOX_BIN_DIR; $p = ${userPathScript}; if (-not (($p -split ';') -contains $d)) { [Environment]::SetEnvironmentVariable('Path', ((@($p.TrimEnd(';'), $d) | Where-Object { $_ }) -join ';'), 'User') }`;
  const done = await run('powershell.exe', ['-NoProfile', '-NonInteractive', '-Command', `${script}; 'ok'`], { AGENTBOX_BIN_DIR: dir });
  if (done !== 'ok') throw new Error(t('web.main.cliPathFailed', { dir }));
}

async function windowsCliStatus(): Promise<CliStatus> {
  const dir = bundledBin() ? managedDir : process.env.AGENTBOX_BIN ? dirname(process.env.AGENTBOX_BIN) : managedDir;
  const onPath = (await userPath()).some((p) => p.replace(/\\+$/, '').toLowerCase() === dir.toLowerCase());
  // Never the app's own AgentBox.exe, which where.exe finds first (clipath.ts).
  const path = firstCli(await run('where.exe', ['agentbox']), process.execPath) ?? (onPath ? join(dir, exe) : null);
  return {
    linkPath: join(dir, exe),
    linked: onPath,
    path,
    version: path ? await run(path, ['--version']) : null,
    onPath,
    bundled: bundledBin() !== null || Boolean(process.env.AGENTBOX_BIN),
    binary: bundledBin() ? agentboxBin() : (process.env.AGENTBOX_BIN ?? null),
  };
}

// The Electron main process. It holds no AgentBox logic: it proxies API calls,
// the event stream, WebSocket streams and media files between the renderer and
// the current environment (this machine's daemon, or one on a hub), signs in to
// hubs, installs the command-line tool, updates the app (updater.ts), and
// keeps the tray icon (tray.ts).
import { isSafeExternalUrl } from './externalurl';
import { app, BrowserWindow, clipboard, dialog, ipcMain, ClipboardItem, powerMonitor, powerSaveBlocker, shell } from 'electron';
import { randomUUID } from 'node:crypto';
import { writeFile } from 'node:fs/promises';
import { arch, hostname } from 'node:os';
import { join } from 'node:path';
import { AppLog, captureConsole, reportSections, type AppError } from './applog';
import { agentboxBin, cliStatus, installCli } from './cli';
import { currentTarget, isLocal, localSocket, savedHubs, saveHubs, setTarget, type SavedHub, type Target } from './connection';
import {
  type ApiResponse,
  ensureDaemon,
  notListening,
  onStaleDaemon,
  request,
  restartDaemon,
  restartIfStale,
  restartStaleDaemon,
  socketPath,
  staleDaemon,
  stopHostDaemon,
  stopStartingDaemon,
  unreachable,
} from './daemon';
import { EventStream } from './events';
import { grantKVM, hostSetupStatus, installWSL, onMac, runHostSetup, runVMMigration, stopVM, vmMigration, type HostSetupOptions } from './hostsetup';
import { startHomeHost, stopHomeHost } from './homehost';
import { handleMedia, registerMediaScheme } from './media';
import { registerBrowserKeys } from './browserkeys';
import { registerBrowserCookies } from './browsercookies';
import { installPhoneWeb } from './phoneweb';
import { onWindows, startRelay, stopRelay } from './relay';
import { guardStdio } from './stdio';
import { setBadge, showNotice, type OSNotice } from './notify';
import { openChatFile } from './chatfiles';
import { pageThumb } from './pagethumbs';
import { registerRender } from './renders';
import { saveShare, showShare } from './share';
import { enableShortcutPortal, registerSnapShortcut, showForSnap } from './snap';
import { Streams } from './streams';
import { installAppUpdates, restartingForUpdate } from './updater';
import { learnMode, linuxVM } from './vmmode';
import { describeGone, goneReport, goneSignature, offersReload, worthReporting, type GoneProcess } from './processgone';
import { ErrorReportSender, outcome, ReportQueue } from './reportqueue';
import type * as T from '../shared/api';
import { denyMedia } from './permissions';
import { keepWindowState, windowOptions } from './windowstate';
import { distro, linuxPath, windowsPath } from './wslpaths';
import { setLanguage, t } from '../shared/i18n/index.ts';
import type { HubInfo, HubPairing, HubPairRequest, HubPairResult, HubSession } from '../shared/api';
import { parseHubLink } from '../shared/hublink';
import type { HubAccount, HubConnectResult } from '../preload';
import './vmpower';
import { keepAwake } from './keepawake';
import { watchHostPower } from './hostpower';
import { AppTray } from './tray';
import { watchLoopLag } from './looplag';
import type { TrayTarget } from './traymodel';

guardStdio();
// The app's log, for problem reports (applog.ts): console and every uncaught
// error. The monitor only watches: Electron still shows its dialog for an
// uncaught exception, and the window is told, to offer or send an error
// report (the renderer's lib/errorReports.ts).
const appLog = new AppLog(app.getPath('logs'));
captureConsole(appLog);
process.on('uncaughtExceptionMonitor', (err) => send('app:error', appLog.error('main', err)));
process.on('exit', () => appLog.flushSync());
// A stall of this process stalls every window: logged, and sent with the
// window's own timing to the daemon's diagnostics (looplag.ts).
watchLoopLag((lag) => {
  appLog.write('LAG', `the main process's event loop stalled ${lag.maxMs} ms (p99 ${lag.p99Ms} ms) in ${lag.windowMs / 1000} s`);
  send('app:mainLag', lag);
});
registerMediaScheme();
registerBrowserKeys();
registerBrowserCookies(ipcMain);
enableShortcutPortal();

let win: BrowserWindow | undefined;

const send = (channel: string, ...args: unknown[]) => {
  if (win && !win.isDestroyed()) win.webContents.send(channel, ...args);
};
const streams = new Streams(send);
const events = new EventStream(
  (event) => {
    send('daemon:event', event);
    showForSnap(win, event);
    tray.onEvent(event);
  },
  (state) => {
    send('daemon:connection', state);
    tray.onConnection();
    // Each time the daemon is back, it may be one that hasn't the web
    // version phones are served (phoneweb.ts).
    // And error reports made while it was away go now (reportqueue.ts).
    if (state.state === 'connected') {
      // A daemon of another version (started by the command line, or one
      // that outlived a restart) is restarted, or shown as stale.
      void restartIfStale().catch(() => {});
      void installPhoneWeb(app.getVersion()).catch((err: unknown) => console.error('phones:', err));
      void errorReports.flush();
    }
  },
);

// The tray's place to open, kept until the window asks for it (tray:take)
// when the window had to be made again for it.
let trayTarget: TrayTarget | undefined;
const tray = new AppTray({
  call: (method, path, body) => callDaemon(method, path, body),
  connected: () => events.state.state === 'connected',
  showWindow,
  open: (target) => {
    if (win && !win.isDestroyed()) {
      showWindow();
      send('tray:open', target);
      return;
    }
    trayTarget = target;
    showWindow();
  },
});
ipcMain.handle('tray:take', () => {
  const target = trayTarget;
  trayTarget = undefined;
  return target ?? null;
});
// With the tray keeping AgentBox running, launching it again shows the one
// already running instead of a second one with a second icon. The second
// one quits before it makes a window, and leaves a Mac's VM to the first.
const duplicate = tray.keepRunning && !app.requestSingleInstanceLock();
if (duplicate) app.quit();
app.on('second-instance', () => showWindow());

// api:request answers a request the daemon never saw, because there was no
// daemon to reach, as the daemon would refuse it: a 503 saying why. That's an
// expected state, not an error, while the VM stops, starts or is paused (the
// forward to its daemon closes each connection then): the renderer shows it
// from the event stream's connection state, and a rejection here would be
// logged by Electron for every call.
ipcMain.handle('api:request', (_event, method: string, path: string, body?: unknown) => callDaemon(method, path, body));

async function callDaemon(method: string, path: string, body?: unknown): Promise<ApiResponse> {
  try {
    return await request(method, path, body);
  } catch (err) {
    if (!isLocal() || !notListening(err)) return unreachable(err);
  }
  try {
    await ensureDaemon();
    return await request(method, path, body);
  } catch (err) {
    return unreachable(err);
  }
}
const setKeepAwake = keepAwake(powerSaveBlocker);
ipcMain.handle('keepawake:set', (event, on: boolean) => setKeepAwake(event.sender, on));
ipcMain.handle('daemon:connection', () => events.state);
// The computer's power, for the renderer's presence lease (main/hostpower.ts):
// powerMonitor answers only once the app is ready.
let hostPower: (() => T.HostPower) | undefined;
ipcMain.handle('power:get', (): T.HostPower => hostPower?.() ?? { onBattery: false });
ipcMain.handle('daemon:stale', () => staleDaemon());
ipcMain.handle('daemon:restartStale', () => restartStaleDaemon());
onStaleDaemon((stale) => send('daemon:stale', stale));
ipcMain.handle('app:info', () => ({
  socket: onWindows ? localSocket() : socketPath,
  version: app.getVersion(),
  electron: process.versions.electron,
  packaged: app.isPackaged,
  platform: process.platform,
}));

// Problem reports: the app's own sections, which the daemon redacts and
// sends with its own (internal/daemon/report.go), and the window's uncaught
// errors, kept with the main process's.
const appReportSections = () =>
  reportSections(appLog, {
    version: app.getVersion(),
    electron: process.versions.electron,
    chrome: process.versions.chrome,
    platform: process.platform,
    arch: arch(),
    target: currentTarget().kind === 'local' ? 'this machine' : 'an environment on a hub',
    vmMode: linuxVM(),
  });
ipcMain.handle('report:sections', appReportSections);
// Automatic error reports, the window's and this process's own, go through
// here, to wait for a daemon that can't be reached (reportqueue.ts).
const errorReports = new ErrorReportSender(new ReportQueue(join(app.getPath('userData'), 'error-reports.json')), async (req) =>
  outcome(await callDaemon('POST', '/v1/reports', req)),
);
ipcMain.handle('report:send', (_event, req: T.ReportRequest) => {
  if (req?.kind !== 'error') throw new Error('only error reports are sent this way');
  return errorReports.send(req);
});
ipcMain.on('report:windowError', (_event, err: Pick<AppError, 'name' | 'message' | 'stack'>) => appLog.windowError(err));
ipcMain.handle('report:openLogs', () => shell.openPath(app.getPath('logs')));

ipcMain.handle('stream:open', (_event, path: string) => {
  if (!path.startsWith('/v1/')) throw new Error(`not an API path: ${path}`);
  return streams.open(path);
});
ipcMain.on('stream:write', (_event, id: number, data: Uint8Array | string) => streams.write(id, data));
ipcMain.on('stream:close', (_event, id: number) => streams.close(id));

// Hubs and environments.

export interface EnvironmentTarget {
  kind: 'local' | 'hub';
  hub?: string;
  email?: string;
  environmentId?: string;
  environmentName?: string;
}

function describe(t: Target): EnvironmentTarget {
  return t.kind === 'local' ? { kind: 'local' } : { kind: 'hub', hub: t.hub.url, email: t.hub.email, environmentId: t.environmentId, environmentName: t.environmentName };
}

// hubCall calls a hub's own API, and throws its error message.
async function hubCall<T>(hub: string, method: string, path: string, token?: string, body?: unknown): Promise<T> {
  const res = await fetch(`${hub}${path}`, {
    method,
    headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body === undefined ? {} : { 'Content-Type': 'application/json' }) },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const text = await res.text();
  if (!res.ok) {
    let message = text.trim() || `HTTP ${res.status}`;
    try {
      message = JSON.parse(text).error ?? message;
    } catch {
      // not JSON
    }
    throw new Error(message);
  }
  return (text ? JSON.parse(text) : undefined) as T;
}

function savedHub(url: string): SavedHub {
  const hub = savedHubs().find((h) => h.url === url);
  if (!hub) throw new Error(t('web.main.notSignedIn', { url }));
  return hub;
}

ipcMain.handle('hubs:list', () => savedHubs().map(({ url, email }) => ({ url, email })));

// What this app calls itself on a hub's list of devices.
function deviceLabel(): string {
  return `AgentBox app on ${hostname()}`;
}

function saveSession(url: string, session: HubSession): HubAccount {
  saveHubs([{ url, email: session.user.email, token: session.token }, ...savedHubs().filter((h) => h.url !== url)]);
  return { url, email: session.user.email };
}

// Accounts made on a hub before pairing still sign in with a password.
ipcMain.handle('hubs:login', async (_event, url: string, email: string, password: string) => {
  url = url.trim().replace(/\/+$/, '');
  if (!/^https?:\/\/[^/]+$/.test(url)) throw new Error(t('web.main.notAHub', { url }));
  return saveSession(url, await hubCall<HubSession>(url, 'POST', '/v1/auth/login', undefined, { email, password, label: deviceLabel() }));
});

// Pairings this app waits on to be approved, by an ID of its own: their
// secrets stay in the main process.
const pairings = new Map<string, { url: string; secret: string; interval: number; cancelled: boolean }>();

// hubs:connect connects to a hub from what was pasted: a setup link signs in
// (or claims the hub) at once; an address asks the hub to approve this app,
// and answers the code to show while hubs:pairWait waits for it.
ipcMain.handle('hubs:connect', async (_event, input: string): Promise<HubConnectResult> => {
  const link = parseHubLink(input);
  if (!link) throw new Error(t('web.main.notAHub', { url: input.trim() }));
  const { url, secret } = link;
  if (secret) return { account: saveSession(url, await hubCall<HubSession>(url, 'POST', '/v1/setup', undefined, { secret, label: deviceLabel() })) };
  // A hub from before pairing has no /v1/hub, and only passwords.
  const res = await fetch(`${url}/v1/hub`);
  if (res.status === 404) return { passwordOnly: url };
  const info = await hubCall<HubInfo>(url, 'GET', '/v1/hub');
  if (!info.claimed) throw new Error(t('web.main.hubUnclaimed'));
  const p = await hubCall<HubPairing>(url, 'POST', '/v1/pair', undefined, { kind: 'device', label: deviceLabel(), hostname: hostname() } satisfies HubPairRequest);
  const id = randomUUID();
  pairings.set(id, { url, secret: p.secret, interval: Math.max(p.interval, 1), cancelled: false });
  return { pairing: { id, url, code: p.code, approveURL: p.approveURL, expiresAt: p.expiresAt, qr: p.qr ?? [], passwords: info.passwords ?? false } };
});
ipcMain.handle('hubs:pairWait', async (_event, id: string): Promise<HubAccount> => {
  const p = pairings.get(id);
  if (!p) throw new Error(t('web.main.pairingGone'));
  try {
    for (;;) {
      await new Promise((resolve) => setTimeout(resolve, p.interval * 1000));
      if (p.cancelled) throw new Error(t('web.main.pairingGone'));
      const r = await hubCall<HubPairResult>(p.url, 'POST', '/v1/pair/token', undefined, { secret: p.secret });
      if (r.status === 'pending') continue;
      if (r.status === 'approved' && r.session) return saveSession(p.url, r.session);
      throw new Error(r.status === 'denied' ? t('web.main.pairingDenied') : t('web.main.pairingExpired'));
    }
  } finally {
    pairings.delete(id);
  }
});
ipcMain.handle('hubs:pairCancel', (_event, id: string) => {
  const p = pairings.get(id);
  if (p) p.cancelled = true;
