// Chromium's processes that die (processgone.ts): a window's renderer, the
// GPU process, the rest. Each is logged and reported once a run; a window
// whose page went, or that nothing may draw any more, is offered a reload.
let quitting = false;
app.on('before-quit', () => (quitting = true));
const goneSeen = new Set<string>();
let reloadAsked = false;

function processGone(gone: GoneProcess, window?: BrowserWindow): void {
  if (!worthReporting(gone, quitting)) return;
  appLog.processGone(describeGone(gone));
  if (!goneSeen.has(goneSignature(gone))) {
    goneSeen.add(goneSignature(gone));
    void errorReports.send(goneReport(gone, appReportSections().find((s) => s.id === 'app'))).catch(() => {});
  }
  if (window && offersReload(gone)) void offerReload(window, gone);
}

// offerReload asks whether to reload the window, one question at a time.
async function offerReload(window: BrowserWindow, gone: GoneProcess): Promise<void> {
  if (reloadAsked || window.isDestroyed()) return;
  reloadAsked = true;
  try {
    const { response } = await dialog.showMessageBox(window, {
      type: 'warning',
      title: 'AgentBox',
      message: gone.process === 'window' ? t('main.windowGone') : t('main.gpuGone'),
      detail: t('main.goneDetail', { reason: gone.reason, code: String(gone.exitCode) }),
      buttons: [t('main.reloadWindow'), t('main.notNow')],
      defaultId: 0,
      cancelId: 1,
    });
    if (response === 0 && !window.isDestroyed()) window.webContents.reload();
  } finally {
    reloadAsked = false;
  }
}

app.on('child-process-gone', (_event, details) =>
  processGone({ process: details.type, reason: details.reason, exitCode: details.exitCode, name: details.name ?? details.serviceName }, win),
);

function createWindow(): void {
  win = new BrowserWindow({
    ...windowOptions(),
    title: 'AgentBox',
    backgroundColor: '#0e0e10',
    autoHideMenuBar: true,
    webPreferences: {
      preload: join(__dirname, '../preload/index.cjs'),
      contextIsolation: true,
      sandbox: true,
    },
  });
  keepWindowState(win);
  const window = win;
  win.webContents.on('render-process-gone', (_event, details) => processGone({ process: 'window', reason: details.reason, exitCode: details.exitCode }, window));
  void win.loadFile(join(__dirname, '../renderer/index.html'));
  // Kept running in the tray (tray.ts), closing the window hides it: it keeps
  // its pages, toasts and OS notifications, and comes back as it was.
  win.on('close', (event) => {
    if (quitting || restartingForUpdate() || !tray.keepRunning) return;
    event.preventDefault();
    window.hide();
  });
  win.on('closed', () => {
    streams.closeAll();
    win = undefined;
  });
}

// showWindow brings the window forward, making it again if it was closed.
function showWindow(): void {
  if (!app.isReady()) return;
  if (!win || win.isDestroyed()) {
    createWindow();
    return;
  }
  if (win.isMinimized()) win.restore();
  win.show();
  win.focus();
}

// A Mac's dock icon clicked while the window is hidden in the menu bar.
app.on('activate', () => showWindow());

void app.whenReady().then(async () => {
  hostPower = watchHostPower(powerMonitor, (power) => send('power:change', power));
  if (duplicate) return;
  handleMedia();
  denyMedia();
  createWindow();
  tray.start();
  registerSnapShortcut();
  // The relay answers at once, whether or not WSL does: it only reaches into
  // the distro on the first request.
  if (onWindows) await startRelay(agentboxBin()).catch(() => {});
  void startHomeHost();
  await learnMode();
  await restartIfStale().catch(() => {});
  events.start();
});

// On Linux, closing the app leaves the daemon and every agent running: they're
// this machine's own, and the command-line tool keeps using them. In VM mode
// that includes the VM: stopping it is the top bar's Free resources, not
// quitting (vmmode.ts).
app.on('window-all-closed', () => {
  events.stop();
  stopHomeHost();
  stopRelay();
  app.quit();
});

// On a Mac they run in AgentBox's VM, and quitting the app, by closing its
// window or with Cmd+Q, stops the VM too. The quit waits for the stop, with the
// window hidden, but not for longer than vmStopTimeout: after that the app quits
// and the stop carries on without it. The next launch starts the VM again, the
// way it starts a daemon that isn't running (ensureDaemon). An app that starts
// no daemon (AGENTBOX_NO_AUTOSTART) never started the VM, and leaves it be.
const vmStopTimeout = 60_000;
let vmStop: 'pending' | 'stopping' | 'done' = onMac && !process.env.AGENTBOX_NO_AUTOSTART && !duplicate ? 'pending' : 'done';

app.on('before-quit', (event) => {
  // Restarting into a new version (updater.ts): the VM stays up for it.
  if (vmStop === 'done' || restartingForUpdate()) return;
  event.preventDefault();
  if (vmStop === 'stopping') return;
  vmStop = 'stopping';
  events.stop();
  stopHomeHost();
  for (const window of BrowserWindow.getAllWindows()) window.hide();
  const stopped = stopStartingDaemon().then(stopVM);
  const timedOut = new Promise<void>((resolve) => setTimeout(resolve, vmStopTimeout));
  void Promise.race([stopped, timedOut])
    .catch((err: unknown) => console.error("stopping AgentBox's VM:", err))
    .finally(() => {
      vmStop = 'done';
      app.quit();
    });
});

// The only surface the renderer gets: the daemon's API, events and WebSocket
// streams, relayed by the main process, plus the command-line tool, a folder
// picker, links and the clipboard.
import { contextBridge, ipcRenderer, type IpcRendererEvent } from 'electron';
import type * as T from '../shared/api';
import type { AppUpdateProgress, AppUpdateResult, AppUpdateSupport } from '../shared/appupdate';
import type { ExtractResult } from '../main/browsercookies';
import type { TraySettings } from '../main/tray';
import type { TrayTarget } from '../main/traymodel';

export interface ApiResponse {
  status: number;
  body: string;
  contentType: string;
}

export interface ConnectionState {
  state: 'connecting' | 'connected' | 'disconnected';
  error?: string;
  starting?: { since: number; step: string }; // the daemon is being started (main/daemon.ts StartProgress)
}

export type { StaleDaemon } from '../main/staledaemon';
import type { StaleDaemon } from '../main/staledaemon';

export interface HostSetupStatus {
  pkexec: string | null;
  user: string;
  running: boolean;
  resizing: boolean; // `agentbox vm resize` is running
  // On a Mac, `agentbox vm krunkit --remake` is running: the VM is gone for
  // a while, which isn't a VM to set up.
  remaking?: boolean;
  // On a Mac, AgentBox runs in a Linux VM, and "host setup" is `agentbox vm
  // init`: what `agentbox vm status --json` says about that VM. null elsewhere.
  vm: VMStatus | null;
  // On Windows, AgentBox runs in a WSL distro of its own, and "host setup" is
  // `agentbox wsl init`: what `agentbox wsl status --json` says about that
  // distro. null elsewhere.
  wsl: WSLStatus | null;
  // On Linux, where AgentBox runs: in a VM of its own (`agentbox vm init`),
  // or, on a machine set up before that, on the machine itself until it moves
  // (`agentbox vm migrate`); and whether it can run the VM. null elsewhere;
  // missing from the web app.
  linux?: LinuxSetup | null;
  // On Linux in VM mode, AgentBox's Cloud Hypervisor VM as `agentbox vm
  // status --json` says: its size, and what it can be resized to, with and
  // without a restart, or state "missing" before vm init made it. null
  // elsewhere; missing from the web app.
  chv?: T.VMStatus | null;
}

// VMMigration is `agentbox vm migrate --status --json`: on a Linux machine
// that runs AgentBox itself, what there is to move into AgentBox's VM, and how
// far a move got. main/hostsetup.ts has the same.
export interface VMMigration {
  state: 'none' | 'available' | 'started' | 'verified' | 'removed';
  projects?: string[];
  agents?: string[];
  oldMachines?: string[]; // what removing the old machines removes, once the move is checked
  backup?: string; // the state.db from before the move
  found?: string[]; // what the check found in the VM
}

export interface LinuxSetup {
  mode: 'host' | 'vm';
  kvm: boolean; // /dev/kvm is there for this user, which the VM needs
  // Why it isn't (main/kvm.ts): "denied" and "module" are what grantKVM
  // fixes, "novirt" is the firmware's. Missing when kvm is true.
  kvmProblem?: 'denied' | 'module' | 'novirt';
  cores: number; // the machine's, the most CPUs the VM can have
  memory: number; // bytes, the machine's
  // The size `agentbox vm init` gives the VM unless it's told otherwise.
  defaultCpus: number;
  defaultMemoryCap: number; // bytes
}

export interface VMStatus {
  // "vz" when the VM is run by Apple's Virtualization framework through
  // AgentBox itself, without Lima (experimental); missing for Lima's.
  driver?: 'vz';
  lima: string; // the limactl in use, "" when Lima isn't installed
  problem?: string; // why there's no VM to use, and what to run
  name: string;
  exists: boolean;
  status?: string; // Running, Stopped, Broken
  cpus?: number;
  memory?: number; // bytes
  disk?: number; // bytes
  limits?: VMLimits; // what `agentbox vm resize` takes on this Mac
  vmType?: string; // vz, krunkit
  // Whether `agentbox vm init` would make the VM with krunkit, which gives
  // memory back to the Mac and has a GPU for agents: on Apple Silicon, before
  // there's a VM and for one made without krunkit. brew: Homebrew can install
  // what's missing.
  krunkit?: { available: boolean; missing?: 'krunkit' | 'driver'; brew?: boolean };
  swap?: T.VMSwap; // what `agentbox vm swap` set (size only)
}

// VMPower is AgentBox's VM in VM mode (the daemon, Incus and every agent in
// one Cloud Hypervisor VM on Linux): its state and its memory, as the host's
// command-line tool reports them (main/vmpower.ts).
export interface VMPower {
  state: VMPowerState;
  memoryUsed: number; // bytes in use inside the VM
  memoryGranted: number; // bytes the VM holds of the host's memory right now
  memoryCap: number; // bytes the VM may grow to at most
  // memoryResident is what the VM holds of the host's memory, its page cache
  // included, and memoryHostCache what the host caches of its disks besides.
  memoryResident?: number;
  memoryHostCache?: number;
  cpus: number;
  error?: string; // why the VM can't be reached or controlled, if it can't
  // pausedForDisk: the supervisor paused it because the host's disk that holds
  // its disk images is nearly full; hostFree is what that disk has free.
  pausedForDisk?: boolean;
  hostFree?: number;
  // disk is its disk images as the host sees them: what they take on the
  // host's disk (allocated) against the size the VM was given (size).
  disk?: T.VMDisk;
  // driver is 'wsl' for AgentBox's WSL distro on Windows (internal/hostwsl):
  // memoryGranted and memoryCap are both what WSL lets it have, and it can't
  // be paused.
  driver?: 'wsl';
}

