function listen<A extends unknown[]>(channel: string, fn: (...args: A) => void): () => void {
  const listener = (_event: IpcRendererEvent, ...args: unknown[]) => fn(...(args as A));
  ipcRenderer.on(channel, listener);
  return () => ipcRenderer.removeListener(channel, listener);
}

const bridge = {
  // Holds the system awake (not the display) while on: agents are at work.
  keepAwake: (on: boolean): Promise<void> => ipcRenderer.invoke('keepawake:set', on),
  // The tray icon (main/tray.ts): whether closing the window keeps AgentBox
  // running there (null where there's no tray, the web app), and whether
  // this computer reviews finished agents, which its count leaves out when
  // not. onOpen gets where a tray menu entry points, including one clicked
  // before this window was made.
  tray: {
    settings: (): Promise<TraySettings | null> => ipcRenderer.invoke('tray:settings'),
    set: (next: Partial<TraySettings>): Promise<TraySettings> => ipcRenderer.invoke('tray:set', next),
    reviewing: (on: boolean) => ipcRenderer.send('tray:reviewing', on),
    onOpen: (fn: (target: TrayOpenTarget) => void) => {
      const off = listen('tray:open', fn);
      void ipcRenderer.invoke('tray:take').then((target: TrayOpenTarget | null) => target && fn(target));
      return off;
    },
  },
  request: (method: string, path: string, body?: unknown): Promise<ApiResponse> =>
    ipcRenderer.invoke('api:request', method, path, body),
  connection: (): Promise<ConnectionState> => ipcRenderer.invoke('daemon:connection'),
  onConnection: (fn: (state: ConnectionState) => void) => listen('daemon:connection', fn),
  onEvent: (fn: (event: unknown) => void) => listen('daemon:event', fn),
  // The computer's power (main/hostpower.ts), for the presence lease
  // (lib/presence.ts): on battery, and its thermal state on a Mac.
  hostPower: (): Promise<T.HostPower> => ipcRenderer.invoke('power:get'),
  onHostPower: (fn: (power: T.HostPower) => void) => listen('power:change', fn),
  // A daemon of another version than this app, still running after an update
  // (main/daemon.ts StaleDaemon); null when it's the app's.
  staleDaemon: (): Promise<StaleDaemon | null> => ipcRenderer.invoke('daemon:stale'),
  onStaleDaemon: (fn: (stale: StaleDaemon | null) => void) => listen('daemon:stale', fn),
  restartStaleDaemon: (): Promise<void> => ipcRenderer.invoke('daemon:restartStale'),
  info: (): Promise<{ socket: string; version: string; electron: string; packaged: boolean; platform: string }> => ipcRenderer.invoke('app:info'),
  // WebSocket endpoints of the API: bytes go as binary messages, strings as text messages.
  stream: {
    open: (path: string): Promise<number> => ipcRenderer.invoke('stream:open', path),
    write: (id: number, data: Uint8Array | string) => ipcRenderer.send('stream:write', id, data),
    close: (id: number) => ipcRenderer.send('stream:close', id),
    onOpened: (fn: (id: number) => void) => listen('stream:opened', fn),
    onData: (fn: (id: number, data: Uint8Array) => void) => listen('stream:data', fn),
    onExited: (fn: (id: number, reason: string) => void) => listen('stream:exited', fn),
  },
  cli: {
    status: (): Promise<CliStatus> => ipcRenderer.invoke('cli:status'),
    install: (): Promise<CliStatus> => ipcRenderer.invoke('cli:install'),
  },
  // `agentbox host setup` as root, through the desktop's own password dialog;
  // on a Mac, `agentbox vm init`, which needs no password. run resolves when
  // the setup succeeded; its output arrives on onOutput as it is printed.
  hostSetup: {
    status: (): Promise<HostSetupStatus> => ipcRenderer.invoke('hostsetup:status'),
    // { vm: true } runs AgentBox in a VM instead, on a Linux machine (`agentbox
    // vm init`, no password), stopping the daemon it ran itself first; cpus
    // and memoryCap (like 12GiB) size it. On a Mac, { driver: 'vz' } makes the
    // experimental vz driver's VM instead of Lima's, and { krunkit: true }
    // installs krunkit with Homebrew first, so the VM is made with it.
    run: (options?: { vm?: boolean; cpus?: number; memoryCap?: string; driver?: 'vz'; krunkit?: boolean }): Promise<{ restarted: boolean }> =>
      ipcRenderer.invoke('hostsetup:run', options),
    // On Linux, /dev/kvm for this user, which AgentBox's VM needs: `agentbox
    // host kvm` through the password dialog, with no new login. Its output
    // arrives on onOutput too.
    grantKVM: (): Promise<void> => ipcRenderer.invoke('hostsetup:kvm'),
    // On Windows, WSL itself: `agentbox wsl install`, behind Windows' own
    // administrator prompt. restart is Windows having to restart to finish.
    installWSL: (): Promise<{ restart: boolean }> => ipcRenderer.invoke('hostsetup:wsl-install'),
    onOutput: (fn: (text: string) => void) => listen('hostsetup:output', fn),
  },
  // On Linux, `agentbox vm migrate`: this machine's own AgentBox moved into
  // AgentBox's VM, and afterwards its old machines removed from its Incus.
  // status is null where there's nothing to say; run resolves when it's done,
  // and its output arrives on onOutput as it is printed.
  vmMigrate: {
    status: (): Promise<VMMigration | null> => ipcRenderer.invoke('vmmigrate:status'),
    run: (): Promise<void> => ipcRenderer.invoke('vmmigrate:run', false),
    removeOld: (): Promise<void> => ipcRenderer.invoke('vmmigrate:run', true),
    onOutput: (fn: (text: string) => void) => listen('vmmigrate:output', fn),
  },
  // `agentbox vm resize`: new CPUs and memory (like 12GiB) for AgentBox's VM.
  // On a Mac that restarts it and stops every agent; on Linux memory is the
  // memory cap, and the VM changes while it runs when it can (chv.live), or
  // restarts with restart; disk (like 200GiB), on Linux, grows its disk. resize
  // resolves when the VM has its new size; its output arrives on onOutput as
  // it is printed.
  vm: {
    resize: (cpus: number, memory: string, restart?: boolean, disk?: string): Promise<void> =>
      ipcRenderer.invoke('vm:resize', cpus, memory, restart, disk),
    // `agentbox vm swap`: a swapfile of size (like 8GiB) in the running VM,
    // or none with null. Every agent keeps running; its output arrives on
    // onSwapOutput, apart from a resize's.
    swap: (size: string | null): Promise<void> => ipcRenderer.invoke('vm:swap', size),
    onSwapOutput: (fn: (text: string) => void) => listen('vm:swap-output', fn),
    onOutput: (fn: (text: string) => void) => listen('vm:output', fn),
    // In VM mode, the VM's power and memory; null when AgentBox isn't in VM
    // mode. act resolves once the VM is in its new state, and after start or
    // resume, once the daemon inside answers.
    power: (): Promise<VMPower | null> => ipcRenderer.invoke('vm:power'),
    act: (action: VMPowerAction): Promise<VMPower> => ipcRenderer.invoke('vm:act', action),
    // What the worktrees and media in the host's home take on its disk,
    // outside the VM's disk images; null when AgentBox isn't in VM mode. It
    // walks both, so it's asked for on demand rather than polled.
    disk: (): Promise<T.VMHomeDisk | null> => ipcRenderer.invoke('vm:disk'),
    // On a Mac whose VM wasn't made with krunkit, `agentbox vm krunkit
    // --remake --yes`: krunkit installed with Homebrew, then the VM deleted,
    // agents' machines and all, and made again with it. Its output arrives on
    // onKrunkitOutput.
    remakeWithKrunkit: (): Promise<void> => ipcRenderer.invoke('vm:krunkit'),
    onKrunkitOutput: (fn: (text: string) => void) => listen('vm:krunkit-output', fn),
  },
  // Hubs this app is connected to, their environments and devices.
  hubs: {
    list: (): Promise<HubAccount[]> => ipcRenderer.invoke('hubs:list'),
    login: (url: string, email: string, password: string): Promise<HubAccount> => ipcRenderer.invoke('hubs:login', url, email, password),
    logout: (url: string): Promise<void> => ipcRenderer.invoke('hubs:logout', url),
    environments: (url: string): Promise<HubEnvironment[]> => ipcRenderer.invoke('hubs:environments', url),
    connect: (input: string): Promise<HubConnectResult> => ipcRenderer.invoke('hubs:connect', input),
    pairWait: (id: string): Promise<HubAccount> => ipcRenderer.invoke('hubs:pairWait', id),
    pairCancel: (id: string): Promise<void> => ipcRenderer.invoke('hubs:pairCancel', id),
    // A pairing another device or an environment asked for, to approve it.
    pairing: (url: string, code: string): Promise<T.HubPairingInfo> => ipcRenderer.invoke('hubs:pairing', url, code),
    decide: (url: string, code: string, approve: boolean): Promise<T.HubPairingInfo> => ipcRenderer.invoke('hubs:decide', url, code, approve),
    devices: (url: string): Promise<T.HubDevice[]> => ipcRenderer.invoke('hubs:devices', url),
    revokeDevice: (url: string, id: string): Promise<void> => ipcRenderer.invoke('hubs:revokeDevice', url, id),
  },
  target: {
    get: (): Promise<EnvironmentTarget> => ipcRenderer.invoke('target:get'),
    set: (target: EnvironmentTarget): Promise<EnvironmentTarget> => ipcRenderer.invoke('target:set', target),
    onChange: (fn: (target: EnvironmentTarget) => void) => listen('target:changed', fn),
  },
  // mediaUrl is where the renderer loads a media item's file from; main/media.ts serves it.
  mediaUrl: (id: string, path?: string): string =>
    `agentbox-media://media/${encodeURIComponent(id)}${path ? '/' + path.split('/').map(encodeURIComponent).join('/') : ''}`,
  // Updating the app in place (main/updater.ts): whether this install can,
  // and the update itself, which restarts the app when it succeeds.
  appUpdate: {
    support: (): Promise<AppUpdateSupport> => ipcRenderer.invoke('appUpdate:support'),
    start: (): Promise<AppUpdateResult> => ipcRenderer.invoke('appUpdate:start'),
    onProgress: (fn: (progress: AppUpdateProgress) => void) => listen('appUpdate:progress', fn),
  },
  // chatImageUrl is where the renderer loads a picture sent in a chat, given
  // its daemon path (.../chat/images/<id>), or frames a Hatch page
  // (.../artifacts/<id>/page); main/media.ts serves it too.
  chatImageUrl: (path: string): string => `agentbox-media://api${path}`,
  // pageThumb is a Hatch page's thumbnail as a data: URL, drawn offscreen from
  // its daemon path and kept by key (<id>@<version>), or null when its HTML
  // can't be had (main/pagethumbs.ts).
  pageThumb: (path: string, key: string): Promise<string | null> => ipcRenderer.invoke('pageThumb:get', path, key),
  // renderUrl is where to frame a page a chat rendered from (main/renders.ts),
  // served with a policy of its own, with or without network.
  renderUrl: (html: string, network: boolean): Promise<string | null> => ipcRenderer.invoke('render:register', html, network),
  // Problem reports: the app's own sections of one (main/applog.ts), a
  // window's uncaught error to keep with them, the main process's uncaught
  // errors as they happen, and the folder the app's logs are in.
  report: {
    sections: (): Promise<T.ReportSection[]> => ipcRenderer.invoke('report:sections'),
    windowError: (err: { name: string; message: string; stack?: string }) => ipcRenderer.send('report:windowError', err),
    onAppError: (fn: (err: { at: string; where: 'main' | 'window'; name: string; message: string; stack?: string }) => void) => listen('app:error', fn),
    // onMainLag is told each time the main process's event loop stalled
    // (main/looplag.ts).
    onMainLag: (fn: (lag: { at: string; maxMs: number; p99Ms: number; windowMs: number }) => void) => listen('app:mainLag', fn),
    openLogs: (): Promise<string> => ipcRenderer.invoke('report:openLogs'),
    // send sends an automatic error report through the main process, which
    // keeps it for later when the daemon can't be reached (main/reportqueue.ts).
    send: (req: T.ReportRequest): Promise<'sent' | 'refused' | 'unreachable' | 'capped'> => ipcRenderer.invoke('report:send', req),
  },
  pickDirectory: (): Promise<string | null> => ipcRenderer.invoke('dialog:directory'),
  // pickFile and pickSaveFile choose a file to open, or where to write one
  // (Settings → Export / Import), as the daemon names it; null when cancelled.
  pickFile: (title: string): Promise<string | null> => ipcRenderer.invoke('dialog:file', title),
  pickSaveFile: (title: string, name: string): Promise<string | null> => ipcRenderer.invoke('dialog:saveFile', title, name),
  openPath: (path: string): Promise<string> => ipcRenderer.invoke('shell:openPath', path),
  // openChatFile opens a file sent in a chat, given its daemon path
  // (.../chat/files/<id>), with the system's default app: main/chatfiles.ts
  // copies it out of the daemon first. It answers an error, or ''.
  openChatFile: (path: string, name: string): Promise<string> => ipcRenderer.invoke('chatFile:open', path, name),
  // saveShare saves an agent's run as one page (.../share), where the user
  // picks: main/share.ts. It answers where, or '' when they didn't pick.
  // showShare shows a page saved there in the file manager.
  saveShare: (path: string, name: string): Promise<string> => ipcRenderer.invoke('share:save', path, name),
  showShare: (file: string): Promise<void> => ipcRenderer.invoke('share:show', file),
  showItem: (path: string): Promise<void> => ipcRenderer.invoke('shell:showItem', path),
  openExternal: (url: string): Promise<void> => ipcRenderer.invoke('shell:openExternal', url),
  // An OS notification, shown only while the window isn't in front (main/notify.ts);
  // onNotificationClick gets its ID when it's clicked.
  notify: (notice: { id: string; title: string; body: string }): Promise<boolean> => ipcRenderer.invoke('notify:show', notice),
  onNotificationClick: (fn: (id: string) => void) => listen('notify:click', fn),
  // The count on the dock or launcher icon: what waits on you (main/notify.ts).
  badge: (count: number) => ipcRenderer.send('notify:badge', count),
  // The passphrase a Chromium browser seals its cookies with, read from the
  // host's keyring (main/browserkeys.ts) for a browser-cookie import, since
  // the daemon in the VM can't reach the keyring. '' when there's none to
  // fetch. The value is passed straight to the import and never kept.
  browserKeyringSecret: (keyring: string): Promise<string> => ipcRenderer.invoke('browserkeys:get', keyring),
  // Reads a Windows browser's cookies on the host by launching the browser
  // itself (main/browsercookies.ts), for a Chrome/Edge/Brave profile the
  // daemon in the VM can't open (app-bound encryption). Returns the decrypted
  // cookies, or an error code; the cookies go straight to the import.
  extractBrowserCookies: (browser: string, profileDir: string): Promise<ExtractResult> =>
    ipcRenderer.invoke('browsercookies:extract', browser, profileDir),
  copyText: (text: string) => ipcRenderer.send('clipboard:write', text),
  // setLanguage tells the main process the app's language, for its dialogs.
  setLanguage: (tag: string) => ipcRenderer.send('app:language', tag),
  readText: (): Promise<string> => ipcRenderer.invoke('clipboard:read'),
  // copyImage puts a PNG on the clipboard; saveImage asks where to save one,
  // named name, and answers whether it was saved.
  copyImage: (png: Uint8Array) => ipcRenderer.send('clipboard:writeImage', png),
  saveImage: (name: string, png: Uint8Array): Promise<boolean> => ipcRenderer.invoke('image:save', name, png),
};

contextBridge.exposeInMainWorld('agentbox', bridge);

export type Bridge = typeof bridge;

// The page of `agentbox machines serve`. The server filters, groups and pages
// (GET /api/items, /api/facets); this keeps the filters in the URL, renders
// pages of cards as they scroll into view, and reuses each card's element
// across refreshes so its thumbnail never reloads. The sidebar's Machines
// section lists the machines (GET /api/machines), and opens one's desktop
// live (#machine=<name>) with the app's VNC client, vnc.js.

const PAGE = 120;
const $ = (id) => document.getElementById(id);

const state = {
  q: "", kind: "", when: "", from: "", to: "", group: "day", source: "",
  repo: "", branch: "", session: "",
};
let items = [];     // loaded so far, in order
let total = 0;
let loading = null; // the page request in flight
let open = new Set(JSON.parse(localStorage.getItem("open") || "[]")); // expanded tree nodes
const cards = new Map(); // id -> card element

// ---- URL state ----

function readURL() {
  const p = new URLSearchParams(location.search);
  for (const k of Object.keys(state)) if (p.has(k)) state[k] = p.get(k);
}
function writeURL() {
  const p = new URLSearchParams();
  for (const [k, v] of Object.entries(state)) if (v && !(k === "group" && v === "day")) p.set(k, v);
  const s = p.toString();
  history.replaceState(null, "", (s ? "?" + s : location.pathname) + location.hash);
}

function query(extra = {}) {
  const p = new URLSearchParams();
  for (const k of ["q", "kind", "group", "source", "repo", "branch", "session"]) if (state[k]) p.set(k, state[k]);
  const [from, to] = dateRange();
  if (from) p.set("from", from);
  if (to) p.set("to", to);
  for (const [k, v] of Object.entries(extra)) p.set(k, v);
  return p.toString();
}

function ymd(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function dateRange() {
  const now = new Date();
  switch (state.when) {
    case "today": return [ymd(now), ""];
    case "7": case "30": {
      const d = new Date(now); d.setDate(d.getDate() - Number(state.when) + 1);
      return [ymd(d), ""];
    }
    case "custom": return [state.from, state.to];
  }
  return ["", ""];
}

// ---- Fetching ----

async function getJSON(url) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(await r.text());
  return r.json();
}

// reload rereads everything shown: the tree and as many items as are loaded
// (at least a page), keeping the scroll position.
async function reload({ keep = false } = {}) {
  const n = keep ? Math.max(items.length, PAGE) : PAGE;
  const [facets, page] = await Promise.all([
    getJSON("/api/facets?" + query()),
    getJSON("/api/items?" + query({ offset: 0, limit: n })),
  ]);
  items = page.items || [];
  total = page.total;
  renderTree(facets);
  renderGrid();
  if (lb.index >= 0) lb.sync();
}

async function loadMore() {
  if (loading || items.length >= total) return;
  loading = getJSON("/api/items?" + query({ offset: items.length, limit: PAGE }));
  try {
    const page = await loading;
    items = items.concat(page.items || []);
    total = page.total;
    renderGrid();
  } finally {
    loading = null;
  }
}

// ---- Tree ----

function node({ cls, name, count, current, chev, onClick, title, src }) {
  const b = document.createElement("button");
  b.className = "node " + (cls || "");
  if (current) b.setAttribute("aria-current", "true");
  if (title) b.title = title;
  const c = document.createElement("span");
  c.className = "chev" + (chev === "open" ? " open" : "");
  c.textContent = chev ? "▶" : "";
  const n = document.createElement("span");
  n.className = "name";
  n.textContent = name;
  b.append(c, n);
  if (src) {
    const s = document.createElement("span");
    s.className = "src"; s.textContent = src;
    b.append(s);
  }
  const k = document.createElement("span");
  k.className = "count"; k.textContent = count;
  b.append(k);
  b.addEventListener("click", onClick);
  return b;
}

function select(repo, branch, session) {
  Object.assign(state, { repo, branch, session });
  if (repo) open.add(repo);
  if (branch) open.add(repo + "\0" + branch);
  saveOpen();
  apply();
}
function toggle(key) {
  open.has(key) ? open.delete(key) : open.add(key);
  saveOpen();
}
function saveOpen() { localStorage.setItem("open", JSON.stringify([...open].slice(-200))); }

function renderTree(f) {
  const t = $("tree");
  const out = [];
  out.push(node({ name: "All media", count: f.total, current: !state.repo, onClick: () => select("", "", "") }));
  const lbl = document.createElement("div");
  lbl.className = "label"; lbl.textContent = "Repositories";
  out.push(lbl);
  $("source").hidden = !f.sources.agentbox && !state.source;
  for (const r of f.repos || []) {
    const rOpen = open.has(r.repo);
    out.push(node({
      name: r.repo, count: r.count, chev: rOpen ? "open" : "closed",
      current: state.repo === r.repo && !state.branch,
      onClick: (e) => {
        if (state.repo === r.repo && !state.branch || e.target.classList.contains("chev")) { toggle(r.repo); renderTree(f); return; }
        select(r.repo, "", "");
      },
    }));
    if (!rOpen) continue;
    for (const b of r.branches) {
      const key = r.repo + "\0" + b.branch;
      const bOpen = open.has(key);
      out.push(node({
        cls: "branch", name: b.branch, count: b.count, title: b.worktree || b.branch,
        chev: b.sessions.length > 1 || b.sessions[0]?.session !== "(no session)" ? (bOpen ? "open" : "closed") : "",
        current: state.repo === r.repo && state.branch === b.branch && !state.session,
        onClick: (e) => {
          if (state.branch === b.branch && state.repo === r.repo && !state.session || e.target.classList.contains("chev")) { toggle(key); renderTree(f); return; }
          select(r.repo, b.branch, "");
        },
      }));
      if (!bOpen) continue;
      for (const s of b.sessions) {
        out.push(node({
          cls: "session", name: s.label || s.session, count: s.count, title: s.session,
          current: state.repo === r.repo && state.branch === b.branch && state.session === s.session,
          onClick: () => select(r.repo, b.branch, s.session),
        }));
      }
    }
  }
  t.replaceChildren(...out);
}

// ---- Grid ----

function fmtDuration(ms) {
  const s = Math.round(ms / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}
function fmtBytes(n) {
  if (n < 1024) return n + " B";
  if (n < 1 << 20) return (n / 1024).toFixed(0) + " KB";
  if (n < 1 << 30) return (n / (1 << 20)).toFixed(1) + " MB";
  return (n / (1 << 30)).toFixed(2) + " GB";
}
function dayLabel(d) {
  const today = new Date(); today.setHours(0, 0, 0, 0);
  const day = new Date(d); day.setHours(0, 0, 0, 0);
  const diff = Math.round((today - day) / 864e5);
  if (diff === 0) return "Today";
  if (diff === 1) return "Yesterday";
  return d.toLocaleDateString(undefined, { weekday: "short", day: "numeric", month: "short", year: day.getFullYear() === today.getFullYear() ? undefined : "numeric" });
}
function timeLabel(d) {
  if (state.group === "day") return d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
  return d.toLocaleDateString(undefined, { day: "numeric", month: "short" }) + " " + d.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" });
}

function groupOf(it) {
  const d = new Date(it.created);
  switch (state.group) {
    case "repo": return { key: it.repo, title: it.repo };
    case "branch": return { key: it.repo + "\0" + it.branch, title: it.branch, sub: it.repo };
    case "session": return { key: it.repo + "\0" + it.branch + "\0" + it.session, title: it.sessionLabel || it.session, sub: `${it.repo} › ${it.branch}` };
  }
  return { key: ymd(d), title: dayLabel(d) };
}

function card(it, i) {
  let el = cards.get(it.id);
  if (!el || el.dataset.sig !== sig(it)) {
    el = document.createElement("div");
    el.className = "card";
    el.tabIndex = 0;
    el.dataset.id = it.id;
    el.dataset.sig = sig(it);
    const th = document.createElement("div");
    th.className = "thumb";
    const img = document.createElement("img");
    img.loading = "lazy";
    img.decoding = "async";
    img.alt = it.caption || it.kind;
    img.src = `/api/items/${encodeURIComponent(it.id)}/thumb`;
    img.addEventListener("error", () => fallbackThumb(th, img, it), { once: true });
    th.append(img);
    if (it.kind === "recording") {
      const b = document.createElement("span");
      b.className = "badge";
      b.innerHTML = '<svg viewBox="0 0 10 10"><path d="M2 1l7 4-7 4z"/></svg>';
      b.append(it.durationMs ? fmtDuration(it.durationMs) : "video");
      th.append(b);
    }
    if (it.source === "agentbox") {
      const t = document.createElement("span");
      t.className = "tag"; t.textContent = "AgentBox";
      th.append(t);
    }
    const cap = document.createElement("div");
    cap.className = "cap" + (it.caption ? "" : " none");
    cap.textContent = it.caption || (it.kind === "recording" ? "Recording" : "Screenshot");
    const meta = document.createElement("div");
    meta.className = "meta";
    const where = document.createElement("span");
    where.textContent = state.group === "branch" || state.group === "session" ? it.sessionLabel || it.session : it.branch;
    where.title = `${it.repo} › ${it.branch} › ${it.sessionLabel || it.session}`;
    const when = document.createElement("span");
    when.className = "when";
    when.textContent = timeLabel(new Date(it.created));
    meta.append(where, when);
    el.append(th, cap, meta);
    cards.set(it.id, el);
  }
  el.dataset.index = i;
  return el;
}
// sig changes when what a card shows does, so it's rebuilt then.
const sig = (it) => [it.caption, it.branch, it.sessionLabel, it.durationMs, state.group].join("\x01");

// A recording without a poster frame (no ffmpeg on this machine) shows its
// own first frame; an image Go couldn't thumbnail shows itself.
function fallbackThumb(th, img, it) {
  const src = `/api/items/${encodeURIComponent(it.id)}/file`;
  if (it.kind === "recording") {
    const v = document.createElement("video");
    v.muted = true; v.preload = "metadata"; v.playsInline = true;
    v.src = src + "#t=0.5";
    img.replaceWith(v);
  } else {
    img.src = src;
  }
}

function renderGrid() {
  const grid = $("grid");
  const out = [];
  let cur = null, section = null;
  items.forEach((it, i) => {
    const g = groupOf(it);
    if (!cur || g.key !== cur) {
      cur = g.key;
      const h = document.createElement("div");
      h.className = "group-head";
      h.textContent = g.title;
      if (g.sub) {
        const s = document.createElement("span");
        s.className = "sub"; s.textContent = g.sub;
        h.append(s);
      }
      section = document.createElement("div");
      section.className = "grid";
      out.push(h, section);
    }
    section.append(card(it, i));
  });
  grid.replaceChildren(...out);
  // Forget cards no longer shown, so the map can't grow forever.
  const shown = new Set(items.map((it) => it.id));
  for (const id of cards.keys()) if (!shown.has(id)) cards.delete(id);

  $("empty").hidden = total > 0;
  const filtered = state.q || state.kind || state.when || state.repo || state.source;
  $("status").textContent = total === 0
    ? (filtered ? "Nothing matches these filters." : "")
    : `${total.toLocaleString()} item${total === 1 ? "" : "s"}` + (items.length < total ? ` · showing ${items.length.toLocaleString()}` : "");
  if (total === 0 && filtered) $("empty").hidden = true;
}

new IntersectionObserver((es) => { if (es.some((e) => e.isIntersecting)) loadMore(); }, { root: $("main"), rootMargin: "1200px" })
  .observe($("more"));

$("grid").addEventListener("click", (e) => {
  const c = e.target.closest(".card");
  if (c) lb.show(Number(c.dataset.index));
});
$("grid").addEventListener("keydown", (e) => {
  const c = e.target.closest(".card");
  if (c && (e.key === "Enter" || e.key === " ")) { e.preventDefault(); lb.show(Number(c.dataset.index)); }
});

// ---- Lightbox ----

const lb = {
  index: -1,
  id: "",
  async show(i) {
    if (i < 0) return;
    if (i >= items.length) {
      if (items.length < total) await loadMore();
      if (i >= items.length) return;
    }
    this.index = i;
    const it = items[i];
    this.id = it.id;
    $("lb").hidden = false;
    document.body.style.overflow = "hidden";
    const file = `/api/items/${encodeURIComponent(it.id)}/file`;
    const m = $("lb-media");
    let el;
    if (it.kind === "recording") {
      el = document.createElement("video");
      el.controls = true; el.autoplay = true; el.preload = "auto"; el.playsInline = true;
      el.src = file;
    } else {
      el = document.createElement("img");
      el.src = file;
      el.alt = it.caption || "Screenshot";
      el.addEventListener("click", () => el.classList.toggle("actual"));
    }
    m.replaceChildren(el);
    $("lb-caption").textContent = it.caption || (it.kind === "recording" ? "Recording" : "Screenshot");
    $("lb-pos").textContent = `${(i + 1).toLocaleString()} of ${total.toLocaleString()}`;
    const rows = [
      ["Repository", it.repo],
      ["Branch", it.branch],
      ["Worktree", it.worktree, true],
      [it.source === "agentbox" ? "Agent" : "Session", it.sessionLabel && it.sessionLabel !== it.session ? `${it.sessionLabel}` : it.session],
      ["Tool", it.tool],
      ["Taken", new Date(it.created).toLocaleString()],
      ["Size", [it.width && it.height ? `${it.width}×${it.height}` : "", it.durationMs ? fmtDuration(it.durationMs) : "", fmtBytes(it.bytes)].filter(Boolean).join(" · ")],
      ["File", it.path, true],
    ];
    const dl = $("lb-meta");
    dl.replaceChildren();
    for (const [k, v, code] of rows) {
      if (!v) continue;
      const dt = document.createElement("dt"); dt.textContent = k;
      const dd = document.createElement("dd");
      if (code) { const c = document.createElement("code"); c.textContent = v; dd.append(c); } else dd.textContent = v;
      dl.append(dt, dd);
    }
    $("lb-copy").disabled = !it.path;
    $("lb-download").href = file + "?download=1";
    $("lb-open").href = file;
    $("lb-prev").disabled = i === 0;
    $("lb-next").disabled = i >= total - 1;
    cards.get(it.id)?.scrollIntoView({ block: "nearest" });
  },
  close() {
    $("lb").hidden = true;
    $("lb-media").replaceChildren();
    document.body.style.overflow = "";
    const c = cards.get(this.id);
    this.index = -1;
    c?.focus({ preventScroll: true });
  },
  // sync follows the item shown after a refresh moved or removed it.
  sync() {
    const i = items.findIndex((it) => it.id === this.id);
    if (i >= 0) { this.index = i; $("lb-pos").textContent = `${(i + 1).toLocaleString()} of ${total.toLocaleString()}`; }
    else if (items.length) this.show(Math.min(this.index, items.length - 1));
    else this.close();
  },
  current() { return items[this.index]; },
};

$("lb-prev").onclick = () => lb.show(lb.index - 1);
$("lb-next").onclick = () => lb.show(lb.index + 1);
$("lb-close").onclick = () => lb.close();
$("lb-stage").addEventListener("click", (e) => { if (e.target === e.currentTarget) lb.close(); });
$("lb-copy").onclick = copyPath;
$("lb-delete").onclick = remove;

async function copyPath() {
  const it = lb.current();
  if (!it?.path) return;
  try {
    await navigator.clipboard.writeText(it.path);
    toast("Path copied");
  } catch {
    toast("Couldn't copy: " + it.path);
  }
}

async function remove() {
  const it = lb.current();
  if (!it) return;
  const d = $("confirm");
  $("confirm-text").textContent = `${it.caption || it.kind} — ${it.repo} › ${it.branch}. ` +
    (it.source === "agentbox" ? "It is deleted from the agent's media in AgentBox too." : "The file is deleted from disk.");
  d.returnValue = "";
  d.showModal();
  await new Promise((r) => d.addEventListener("close", r, { once: true }));
  if (d.returnValue !== "ok") return;
  const r = await fetch(`/api/items/${encodeURIComponent(it.id)}`, { method: "DELETE", headers: { "X-Machines": "1" } });
  if (!r.ok) { toast("Couldn't delete: " + (await r.text())); return; }
  toast("Deleted");
  const at = lb.index;
  items.splice(at, 1);
  total--;
  cards.delete(it.id);
  renderGrid();
  if (items.length) lb.show(Math.min(at, items.length - 1)); else lb.close();
  reload({ keep: true });
}

function toast(text) {
  const t = $("toast");
  t.textContent = text;
  t.classList.add("show");
  clearTimeout(toast.t);
  toast.t = setTimeout(() => t.classList.remove("show"), 1800);
}

document.addEventListener("keydown", (e) => {
  if ($("confirm").open) return;
  if (!$("mv").hidden) {
    // In control, every key is the machine's.
    if (mv.control) return;
    if (e.key === "Escape" && !document.fullscreenElement) { e.preventDefault(); mv.close(); }
    else if (e.key === "f" && !e.ctrlKey && !e.metaKey) { e.preventDefault(); mv.fullscreen(); }
    return;
  }
  const typing = e.target.matches?.("input, select, textarea");
  if (!$("lb").hidden) {
    if (e.key === "Escape") { e.preventDefault(); lb.close(); }
    else if (e.key === "ArrowLeft" && !(e.target instanceof HTMLVideoElement)) { e.preventDefault(); lb.show(lb.index - 1); }
    else if (e.key === "ArrowRight" && !(e.target instanceof HTMLVideoElement)) { e.preventDefault(); lb.show(lb.index + 1); }
    else if (e.key === "Delete" || e.key === "Backspace") { e.preventDefault(); remove(); }
    else if (e.key === "c" && !e.ctrlKey && !e.metaKey) copyPath();
    else if (e.key === "d" && !e.ctrlKey && !e.metaKey) $("lb-download").click();
    else if (e.key === " " && !(e.target instanceof HTMLVideoElement)) {
      const v = $("lb-media").querySelector("video");
      if (v) { e.preventDefault(); v.paused ? v.play() : v.pause(); }
    }
    return;
  }
  if (e.key === "/" && !typing) { e.preventDefault(); $("q").focus(); }
});

// ---- Controls ----

function apply() {
  writeURL();
  $("main").scrollTop = 0;
  reload().catch((e) => toast(String(e.message || e)));
}

function syncControls() {
  $("q").value = state.q;
  for (const b of $("kind").children) b.setAttribute("aria-pressed", String(b.dataset.v === state.kind));
  $("when").value = state.when;
  $("range").hidden = state.when !== "custom";
  $("from").value = state.from;
  $("to").value = state.to;
  $("group").value = state.group || "day";
  $("source").value = state.source;
}

let qTimer;
$("q").addEventListener("input", () => {
  clearTimeout(qTimer);
  qTimer = setTimeout(() => { state.q = $("q").value.trim(); apply(); }, 150);
});
$("q").addEventListener("keydown", (e) => { if (e.key === "Escape") { $("q").value = ""; $("q").dispatchEvent(new Event("input")); $("q").blur(); } });
$("kind").addEventListener("click", (e) => {
  const b = e.target.closest("button");
  if (!b) return;
  state.kind = b.dataset.v;
  syncControls(); apply();
});
$("when").addEventListener("change", () => { state.when = $("when").value; syncControls(); apply(); });
$("from").addEventListener("change", () => { state.from = $("from").value; apply(); });
$("to").addEventListener("change", () => { state.to = $("to").value; apply(); });
$("group").addEventListener("change", () => { state.group = $("group").value; apply(); });
$("source").addEventListener("change", () => { state.source = $("source").value; apply(); });

const zoom = localStorage.getItem("zoom");
if (zoom) $("zoom").value = zoom;
const setZoom = () => document.documentElement.style.setProperty("--card", $("zoom").value + "px");
setZoom();
$("zoom").addEventListener("input", () => { setZoom(); localStorage.setItem("zoom", $("zoom").value); });

$("theme").addEventListener("click", () => {
  const dark = getComputedStyle(document.documentElement).colorScheme === "dark";
  const next = dark ? "light" : "dark";
  document.documentElement.dataset.theme = next;
  localStorage.setItem("theme", next);
});

// ---- Machines ----

let machines = [];
let machinesError = "";

function machineTitle(m) {
  const base = m.worktree.split("/").filter(Boolean).pop() || m.name;
  if (m.repo && m.branch) return `${m.repo.split("/").pop()} · ${m.branch}`;
  return m.branch ? `${base} · ${m.branch}` : base;
}
function fmtUptime(started) {
  const s = Math.max(0, Math.floor((Date.now() - new Date(started)) / 1000));
  if (s < 60) return "up " + s + "s";
  const m = Math.floor(s / 60);
  if (m < 60) return "up " + m + "m";
  const h = Math.floor(m / 60);
  if (h < 24) return `up ${h}h ${m % 60}m`;
  return `up ${Math.floor(h / 24)}d ${h % 24}h`;
}
function machineSub(m) {
  if (m.busy) return m.busy[0].toUpperCase() + m.busy.slice(1) + "…";
  if (m.error) return m.error;
  if (!m.running) return "Stopped";
  const parts = [];
  if (m.started) parts.push(fmtUptime(m.started));
  if (m.memory) parts.push(m.limit ? `${m.memory} of ${m.limit}` : m.memory);
  return parts.join(" · ") || "Running";
}
function dotClass(m) { return "dot" + (m.busy ? " busy" : m.running ? " on" : ""); }

async function loadMachines() {
  try {
    const r = await getJSON("/api/machines");
    machines = r.machines || [];
    machinesError = r.error || "";
  } catch (e) {
    machinesError = String(e.message || e);
  }
  renderMachines();
  mv.sync();
}

function renderMachines() {
  const out = [];
  const lbl = document.createElement("div");
  lbl.className = "label"; lbl.textContent = "Machines";
  out.push(lbl);
  if (machinesError || !machines.length) {
    const p = document.createElement("div");
    p.className = "none" + (machinesError ? " err" : "");
    p.textContent = machinesError || "None yet: an AI tool's machine_start makes one for its worktree.";
    out.push(p);
  }
  for (const m of machines) {
    const row = document.createElement("div");
    row.className = "machine";
    if (mv.name === m.name) row.setAttribute("aria-current", "true");
    const dot = document.createElement("span");
    dot.className = dotClass(m);
    const open = document.createElement("button");
    open.className = "open";
    open.title = m.running ? `Watch ${m.worktree} live` : m.worktree;
    const t = document.createElement("span");
    t.className = "title"; t.textContent = machineTitle(m);
    const sub = document.createElement("span");
    sub.className = "sub" + (m.error && !m.busy ? " err" : ""); sub.textContent = machineSub(m);
    open.append(t, sub);
    open.addEventListener("click", () => { location.hash = "machine=" + encodeURIComponent(m.name); });
    row.append(dot, open, powerButton(m, "power"));
    out.push(row);
  }
  $("machines").replaceChildren(...out);
}

function powerButton(m, cls) {
  const b = document.createElement("button");
  b.className = cls;
  setPower(b, m);
  return b;
}
function setPower(b, m) {
  b.textContent = m.running ? "Stop" : "Start";
  b.disabled = !!m.busy;
  b.onclick = (e) => { e.stopPropagation(); power(m, m.running ? "stop" : "start"); };
}

async function power(m, op) {
  const r = await fetch(`/api/machines/${encodeURIComponent(m.name)}/${op}`, { method: "POST", headers: { "X-Machines": "1" } });
  if (!r.ok) toast(await r.text());
  loadMachines();
}

// mv is the live view of one machine, opened by #machine=<name>.
const mv = {
  name: "",
  session: null,
  control: false,
  connected: false,
  open(name) {
    if (this.name === name) return;
    this.close({ keepHash: true });
    this.name = name;
    $("mv").hidden = false;
    document.body.style.overflow = "hidden";
    this.setControl(false);
    this.sync();
    renderMachines();
  },
  machine() { return machines.find((m) => m.name === this.name); },
  // sync follows the machine: connects when it runs, says why not otherwise.
  sync() {
    if (!this.name) return;
    const m = this.machine();
    $("mv-name").textContent = m ? machineTitle(m) : this.name;
    $("mv-sub").textContent = m ? m.worktree : "";
    $("mv-dot").className = m ? dotClass(m) : "dot";
    $("mv-power").hidden = !m;
    if (m) setPower($("mv-power"), m);
    const msg = $("mv-msg");
    if (m && m.running) {
      msg.hidden = true;
      if (!this.session) this.connect();
    } else {
      this.disconnect();
      msg.hidden = false;
      msg.textContent = !m ? (machinesError || "There's no machine called " + this.name + ".")
        : m.busy ? m.busy[0].toUpperCase() + m.busy.slice(1) + "…"
        : m.error || "This machine is stopped. Start it to watch its desktop.";
    }
    this.state();
  },
  async connect() {
    const name = this.name;
    this.session = {}; // connecting
    let view;
    try {
      view = await import("./vnc.js");
    } catch (e) {
      this.session = null;
      toast("Couldn't load the viewer: " + (e.message || e));
      return;
    }
    if (this.name !== name || !this.session) return;
    this.session = view.open($("mv-view"), name, (connected) => {
      this.connected = connected;
      this.state();
      if (connected) this.session?.setControl(this.control);
    });
  },
  disconnect() {
    this.session?.close?.();
    this.session = null;
    this.connected = false;
    $("mv-view").replaceChildren();
  },
  state() {
    const m = this.machine();
    $("mv-state").textContent = !m || !m.running ? "" : this.connected ? (this.control ? "Live · you're in control" : "Live · view only") : "Connecting…";
  },
  setControl(on) {
    this.control = on;
    $("mv-control").setAttribute("aria-pressed", String(on));
    $("mv-control").textContent = on ? "Release control" : "Take control";
    $("mv-paste").disabled = !on;
    $("mv-cover").hidden = on;
    this.session?.setControl?.(on);
    this.state();
  },
  fullscreen() {
    if (document.fullscreenElement) document.exitFullscreen();
    else $("mv-screen").requestFullscreen?.().catch(() => {});
  },
  close({ keepHash = false } = {}) {
    if (!this.name) return;
    this.disconnect();
    this.name = "";
    this.setControl(false);
    $("mv").hidden = true;
    document.body.style.overflow = "";
    if (document.fullscreenElement) document.exitFullscreen();
    if (!keepHash && location.hash) history.replaceState(null, "", location.pathname + location.search);
    renderMachines();
  },
};

$("mv-control").addEventListener("click", () => mv.setControl(!mv.control));
$("mv-paste").addEventListener("click", async () => {
  try {
    await mv.session?.paste?.();
    toast("Sent your clipboard: paste it on the machine");
  } catch {
    toast("The browser didn't let the page read your clipboard");
  }
});
$("mv-full").addEventListener("click", () => mv.fullscreen());
$("mv-close").addEventListener("click", () => mv.close());

function followHash() {
  const name = new URLSearchParams(location.hash.slice(1)).get("machine");
  if (name) mv.open(name);
  else mv.close({ keepHash: true });
}
window.addEventListener("hashchange", followHash);

// Machines are polled: their uptime and memory change all the time, and
// starting one is the runtime's, not the page's, to report.
setInterval(() => { if (!document.hidden) loadMachines(); }, 3000);
document.addEventListener("visibilitychange", () => { if (!document.hidden) loadMachines(); });

// ---- Live updates ----

function listen() {
  const es = new EventSource("/api/events");
  let first = true;
  es.addEventListener("hello", () => {
    // After a reconnect (the server restarted), catch up.
    if (!first) reload({ keep: true }).catch(() => {});
    first = false;
  });
  let t;
  es.addEventListener("change", () => {
    clearTimeout(t);
    t = setTimeout(() => reload({ keep: true }).catch(() => {}), 150);
  });
}

readURL();
syncControls();
reload().catch((e) => toast(String(e.message || e)));
listen();
followHash();
loadMachines();

import { createServer } from "node:http";
import { readFileSync } from "node:fs";
import { hostname } from "node:os";

const port = Number(process.env.PORT ?? 3000);

const escape = (s) => s.replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);

// A sign-in page for browser demos. The signed-in user is kept in a cookie.
function login(req, res) {
  const user = new URL(req.url, "http://localhost").searchParams.get("user");
  if (user !== null) {
    res.writeHead(303, { location: "/login", "set-cookie": `user=${encodeURIComponent(user)}; Path=/; SameSite=Lax` });
    return res.end();
  }
  const cookie = /(?:^|;\s*)user=([^;]*)/.exec(req.headers.cookie ?? "");
  const name = cookie ? decodeURIComponent(cookie[1]) : "";
  const title = name ? `Signed in as ${escape(name)}` : "Not signed in";
  res.setHeader("content-type", "text/html; charset=utf-8");
  res.end(`<!doctype html>
<title>${title}</title>
<body style="font: 22px system-ui, sans-serif; margin: 3rem">
<h1>${title}</h1>
<p>Served by ${hostname()}</p>
${name ? '<a href="/login?user=">Sign out</a>' : '<form><input name="user" placeholder="Your name" autofocus> <button>Sign in</button></form>'}
</body>
`);
}

createServer((req, res) => {
  if (req.url.startsWith("/login")) return login(req, res);
  res.setHeader("content-type", "application/json");
  res.end(
    JSON.stringify({
      host: hostname(),
      message: readFileSync(new URL("./message.txt", import.meta.url), "utf8").trim(),
    }) + "\n",
  );
}).listen(port, () => console.log(`listening on :${port}`));

// The language the app speaks, and its messages. One language at a time for
// the whole app: the renderer sets it from the daemon's Settings.language and
// re-renders (renderer/lib/i18n.tsx), and the main process is told it for its
// own few dialogs. Dates and numbers are written the language's way too.
//
// en-US is the source: its catalog has every key, and another language's lacking
// one shows en-US's rather than a key. The Go side — the CLI, the brief, the
// agents' chats — stays in English.
import { enUS, type MessageKey, type Messages } from './en-US.ts';
import { format, formatNumberIn, formatParts, type Values } from './format.ts';
import { languages, type Language } from './languages.ts';

export type { MessageKey, Messages, Values, Language };
export { languages };

export const defaultLanguage = 'en-US';

let current: Language = languages[0];
const listeners = new Set<() => void>();

// resolveLanguage is the language on the list for a tag: the tag itself, else
// one with its primary language ("pt-PT" gets pt-BR), else en-US.
export function resolveLanguage(tag: string | null | undefined): Language {
  if (!tag) return languages[0];
  const lower = tag.toLowerCase();
  return (
    languages.find((l) => l.tag.toLowerCase() === lower) ??
    languages.find((l) => l.tag.split('-')[0].toLowerCase() === lower.split('-')[0]) ??
    languages[0]
  );
}

// language is the tag of the language the app speaks now.
export function language(): string {
  return current.tag;
}

// setLanguage switches the app to a language, telling every subscriber.
export function setLanguage(tag: string | null | undefined): void {
  const next = resolveLanguage(tag);
  if (next === current) return;
  current = next;
  for (const listener of listeners) listener();
}

export function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

function message(key: MessageKey): string {
  return current.messages[key] ?? enUS[key] ?? key;
}

// t is a message in the current language, with its values put in.
export function t(key: MessageKey, values?: Values): string {
  return format(message(key), values, current.tag);
}

// tParts is t before the parts are joined, for values that aren't text.
export function tParts(key: MessageKey, values?: Values): unknown[] {
  return formatParts(message(key), values, current.tag);
}

export function formatNumber(n: number, options?: Intl.NumberFormatOptions): string {
  return formatNumberIn(current.tag, n, options);
}

type When = Date | string | number;

export function formatDate(when: When, options: Intl.DateTimeFormatOptions = { dateStyle: 'medium' }): string {
  return new Intl.DateTimeFormat(current.tag, options).format(new Date(when));
}

export function formatTime(when: When, options: Intl.DateTimeFormatOptions = { timeStyle: 'short' }): string {
  return new Intl.DateTimeFormat(current.tag, options).format(new Date(when));
}

export function formatDateTime(when: When, options: Intl.DateTimeFormatOptions = { dateStyle: 'medium', timeStyle: 'short' }): string {
  return new Intl.DateTimeFormat(current.tag, options).format(new Date(when));
}

// formatList joins items the language's way: "a, b and c", "a, b e c".
export function formatList(items: string[], type: Intl.ListFormatType = 'conjunction'): string {
  return new Intl.ListFormat(current.tag, { style: 'long', type }).format(items);
}

#!/usr/bin/env node
"use strict";

const { spawn } = require("child_process");

const SUPPORTED = [
  "linux-x64",
  "linux-arm64",
  "darwin-x64",
  "darwin-arm64",
  "win32-x64",
  "win32-arm64",
];

function binaryPath() {
  if (process.env.AGENTBOX_HUB_BINARY) return process.env.AGENTBOX_HUB_BINARY;
  const key = `${process.platform}-${process.arch}`;
  const exe = process.platform === "win32" ? "agentbox-hub.exe" : "agentbox-hub";
  try {
    return require.resolve(`@agentbox-hub/${key}/bin/${exe}`);
  } catch (e) {
    console.error(
      `agentbox-hub: no binary for this platform (${key}).\n\n` +
        `The package @agentbox-hub/${key} is not installed. If your platform is supported, ` +
        `reinstall without --no-optional / --omit=optional (for example "npm i agentbox-hub"), ` +
        `since the binary comes in an optional dependency.\n\n` +
        `Supported platforms: ${SUPPORTED.join(", ")}.\n` +
        `To use a binary you built yourself, set AGENTBOX_HUB_BINARY to its path.`
    );
    process.exit(1);
  }
}

const child = spawn(binaryPath(), process.argv.slice(2), { stdio: "inherit" });

for (const sig of ["SIGINT", "SIGTERM", "SIGHUP"]) {
  process.on(sig, () => {
    try {
      child.kill(sig);
    } catch (e) {
      // already gone
    }
  });
}

child.on("error", (err) => {
  console.error(`agentbox-hub: could not run ${child.spawnfile}: ${err.message}`);
  process.exit(1);
});

child.on("exit", (code, signal) => {
  if (signal) {
    // Remove our handlers so the re-raised signal takes the default action.
    for (const sig of ["SIGINT", "SIGTERM", "SIGHUP"]) process.removeAllListeners(sig);
    process.kill(process.pid, signal);
    return;
  }
  process.exit(code === null ? 1 : code);
});

